// === Tab: IlluminationShader ===

/**
 * Frag shader to compute global illumination per pixel
 **/
const illumShaderSrc = `
precision highp float;
uniform vec2 u_pixel; // Size of a pixel
uniform sampler2D u_tex; // The distance map texture
uniform sampler2D u_color; // The distance map texture
uniform float u_time; // Time in seconds
uniform float u_max_dist; // Maximum distance for light to travel in pixels
uniform int u_max_rays; // Maximum number of rays per pixel
uniform float u_att_pow; // Attenuation power
varying vec2 vTexCoord; // Texture coordinate of the pixel

// constants
#define PI 3.141596
#define MAX_RAYS_PER_PIXEL 128
#define MAX_RAYMARCH_STEPS 100

float random (vec2 st) {
  return fract(sin(dot(st.xy, vec2(12.9898,78.233))) * 43758.5453123);
}

vec3 lin_to_srgb (vec3 color) {
   vec3 x = color.rgb * 12.92;
   vec3 y = 1.055 * pow(clamp(color, 0.0, 1.0), vec3(0.4166667)) - 0.055;
   vec3 clr = color;
   clr.r = (color.r < 0.0031308) ? x.r : y.r;
   clr.g = (color.g < 0.0031308) ? x.g : y.g;
   clr.b = (color.b < 0.0031308) ? x.b : y.b;
   return clr;
}

vec3 raymarch(vec2 origin, vec2 dir) {
   float current_dist = 0.0;
   for(int i = 0; i < MAX_RAYMARCH_STEPS; i++) {
      vec2 point_coords = origin + dir * current_dist;
			vec2 uv = point_coords * u_pixel;

      // early exit if we hit the edge of the screen. 
			// or if light too far to matter
      if(uv.x > 1.0 || uv.x < 0.0 || uv.y > 1.0 || uv.y < 0.0 || current_dist > u_max_dist) return vec3(-1);

			vec4 sample = texture2D (u_tex, uv); // Get distance field
			if (sample.a >= 1.) {
				// Hit an original pixel.
				// Encode distance in the alpha channel
				return vec3(uv, current_dist);
			} 

      // if we don't hit a surface, continue marching along the ray.
      current_dist += sample.b;
   }
   return vec3(-1);
}

void main() {
	vec3 pixel_col = vec3(0.0);

	// get fragment texture coordinates
	vec2 uv = vTexCoord;

	// get fragment pixel coordinates
	vec2 pos = uv / u_pixel;

	float rand2pi = random(uv * vec2(u_time, -u_time)) * 2.0 * PI;
	float golden_angle = PI * 0.7639320225; // magic number that gives us a good ray distribution.

	for(int i = 0; i < MAX_RAYS_PER_PIXEL; i++) {
	  if (i >= u_max_rays) break; 
		// get our ray dir by taking the random angle and adding golden_angle * ray number.
    float cur_angle = rand2pi + golden_angle * float(i);
    vec2 ray_dir = normalize(vec2(cos(cur_angle), sin(cur_angle)));
   	vec3 hit = raymarch(pos, ray_dir);
		float dist = hit.b;
		if(dist > -1.) { // we hit something
			if (dist <= 0.01) {
				// Original pixel - early return  
				vec4 col = texture2D (u_color, uv);
				gl_FragColor = vec4(col.rgb,1.);
				return;
			}
			else {
			  // Empty pixel originally
			  vec4 col = texture2D (u_color, hit.rg);
				float id = col.a;
				if (id < 100.0) {
					// Convention: id > 100 ? occluder : light
					float emission = pow((u_max_dist-min(dist,u_max_dist))/u_max_dist,u_att_pow);
					pixel_col += col.rgb * emission;
				}
			}
		}
	}
	gl_FragColor = vec4 (lin_to_srgb(pixel_col / float(u_max_rays)), 1.);
}
`;

// === Tab: JumpFloodShader ===
/**
 * Frag shader to jump flood one step
 **/
const floodShaderSrc = `
precision highp float;
uniform vec2 u_pixel; // Size of a pixel
uniform sampler2D u_tex; // The texture
uniform float u_step; // Jump flood step
varying vec2 vTexCoord; // Texture coordinate of the pixel
#define FAR 1e9

void main() {
	vec4 p = texture2D (u_tex,vTexCoord);

	if (p.a >= 1.) {  
		// An original pixel
		gl_FragColor = p;
		return;
	}

	// An originally empty pixel
	vec2 closest_pixel = vec2(-1);
	float closest_dist = FAR; // Very far...
	if (p.a == -1.) {
		// already visited
		closest_pixel = p.rg;
		closest_dist = p.b;
	}

  for (int y = -1; y <= 1; ++y) {
    for (int x = -1; x <= 1; ++x) { 
			vec2 v = vec2(x,y) * u_step; // Vector from pos to neighbor in pixel coordinates
			vec2 uv = vTexCoord + v * u_pixel; // Texture coord of neighbor
			if (uv.x < 0. || uv.x >= 1. || uv.y < 0. || uv.y >= 1.) continue;
			vec4 sample = texture2D (u_tex, uv);

			if (sample.a >= 1.) {  // An original pixel neighbor
				float dist = length(v);
				if (dist < closest_dist) {
					closest_dist = dist;
					closest_pixel = uv;
				}
			} else if (sample.a <= -1.) { // A visited empty pixel neighbor
				float dist = length((sample.rg-vTexCoord)/u_pixel);
				if (dist < closest_dist) {
					closest_dist = dist;
					closest_pixel = sample.rg;
				}
			}
		}
	}
	if (closest_dist < FAR) p = vec4(closest_pixel,closest_dist,-1.);
	gl_FragColor = p;
}
`;


// === Tab: OtherShaders ===
/**
 * Vertex shader 
 **/
const vertexShaderSrc = `
precision highp float;
uniform mat4 uModelViewMatrix;
uniform mat4 uProjectionMatrix;

attribute vec3 aPosition;
attribute vec2 aTexCoord;
varying vec2 vTexCoord;

void main() {
  vTexCoord = aTexCoord;
  vec4 positionVec4 = vec4(aPosition, 1.0);
  gl_Position = uProjectionMatrix * uModelViewMatrix * positionVec4;
}`;

/**
 * Frag shader to draw initial regions
 **/
const paintShaderSrc = `
precision highp float;
uniform vec4 u_color;
void main() {
		gl_FragColor = u_color;
}
`;

/**
 * Frag shader to display voronoi regions
 **/
const voronoiShaderSrc = `
precision highp float;
uniform vec2 u_pixel; // Size of a pixel
uniform sampler2D u_tex; // The texture
varying vec2 vTexCoord; // Texture coordinate of the pixel

void main() {
	vec4 p = texture2D (u_tex,vTexCoord);
	if (p.a >= 1.) {
		gl_FragColor = vec4(p.rgb,1.);
	}
	else if (p.a <= -1.) {
	  vec2 uv = p.rg; // * u_pixel;
		vec4 pixel = texture2D (u_tex,uv);
		gl_FragColor = vec4(pixel.rgb, 0.9);
	}
	else {
		gl_FragColor = vec4(1.); // white
	}
}
`;

/**
 * Frag shader to compute distance fields
 **/
const distanceShaderSrc = `
precision highp float;
uniform vec2 u_pixel; // Size of a pixel
uniform sampler2D u_tex; // The texture
varying vec2 vTexCoord; // Texture coordinate of the pixel

void main() {
	vec4 p = texture2D (u_tex,vTexCoord);
	if (p.a >= 1.) { // Original pixel
		gl_FragColor = vec4(0.,0.,0.,p.a);
	}
	else if (p.a <= -1.) { // Empty pixel visited by the jump flood.
	  vec2 uv = p.rg; 
		vec4 pixel = texture2D (u_tex,uv);
		float dist = length((p.rg-vTexCoord)/u_pixel); // distance in pixels
		gl_FragColor = vec4(uv, dist, -1.);
	}
	else { // Should never happen. All pixels should have been visited by the jump flood.
		gl_FragColor = vec4(0.,0.,1.,0.); 
	}
}
`;

/**
 * Displays the distance field
 **/
const distanceShowShaderSrc = `
precision highp float;
uniform sampler2D u_tex; // The texture
uniform sampler2D u_color; // The color map
varying vec2 vTexCoord; // Texture coordinate of the pixel

void main() {
  float maxDist = 500.;
	vec4 p = texture2D (u_tex,vTexCoord);
	if (p.a >= 1.) {
	  vec4 col = texture2D (u_color, vTexCoord);
		gl_FragColor = vec4(col.rgb, 1.);
	} 
	else { // p.a <= -1
		float dist = p.b;
		float dcurve = mod(floor(dist),20.);
		if (dcurve > 1.) {
			vec4 col = texture2D (u_color,p.rg);
			float alpha = clamp((maxDist-dist)/maxDist,0.,1.);
			gl_FragColor = vec4(col.rgb, alpha); 
		}
		else {
			gl_FragColor = vec4(0., 0., 0., 1.); 
		}
	}
}
`;

/**
 * A gaussian blur shader (not used)
 **/
const blurFilterSrc = `
precision highp float;
uniform sampler2D tex0; // The texture
uniform vec2 texelSize;
uniform vec2 canvasSize;
varying vec2 vTexCoord; // Texture coordinate of the pixel

#define gaussian_blur mat3(1, 2, 1, 2, 4, 2, 1, 2, 1) * 0.0625

// Iterate over all pixels in 3x3 kernel area
vec4 convolute(vec2 uv, mat3 kernel) {
    vec4 color = vec4(0);

    float direction[3];
		direction[0] = -1.;
		direction[1] = 0.;
		direction[2] = 1.;
    for (int x = 0; x < 3; x++)
    {
        for (int y = 0; y < 3; y++)
        {
            vec2 offset = vec2(direction[x], direction[y]) /canvasSize;//* texelSize;
            color += texture2D(tex0, uv+offset) * kernel[x][y];
        }
    }
    return color;
}

void main() {
	gl_FragColor = convolute(vTexCoord, gaussian_blur);
}
`;





// === Tab: RandomSticks ===
function randomSticks() {
	var t = millis()/10000;
	let k = floor(map(obj_density,0,10,10,50));
	for (let i = 0; i < k; i += 1) {
		// Convention: id > 100 ? occluder : light
		if(i>=k/3) 
			paintShader.setUniform("u_color", [random(.5,1),random(.5,1),random(.5,1),i+1]);
		else
			paintShader.setUniform("u_color", [random(.5,1), random(.5,1), random(.5,1), i+100]);

		let [x,y] = [
			map(noise(i*10, 0, t), 0, 1, -width/2,width/2),
			map(noise(i*10, 100, t), 0, 1, -height/2,height/2)
		];
		let vec = createVector(20,0);
		push();
		translate (x,y);
		rotate(map(noise(i*10,1000,t*4), 0, 1, -PI,PI));
		rect(-40,-5,80,10);
		pop()
		}
}

// === Tab: circleCarousel ===
function circleCaroussel() {
	var t = millis()/1000;
	let R = max(width, height) / 2;
	let R1 = R*0.8;
	let R2 = R*0.4;
	let n = floor(map(obj_density,0,10,3,30));
	t*=n/10;
	let dang = TAU / n;
	let sz = TAU * R2 / n / 2;
	for (let i = 0; i < n; i++) {
		let d = sin(t*dang);
		let r = (R1+R2)/2 + d * (R1-R2)/2;
		let v = createVector (r,0).rotate((i+t)*dang);
		paintShader.setUniform("u_color", [random(0.5,1),random(0.5,1),random(0.5,1),i+1]);
		circle (v.x, v.y,sz);
		r = (R1+R2)/2 - d * (R1-R2)/2;
		v = createVector (r,0).rotate((t+i+0.5)*dang);
		paintShader.setUniform("u_color", [random(0.5,1),random(0.5,1),random(0.5,1),i+100]);
		circle (v.x, v.y,sz);
	}
}

// === Tab: rotatingCubes ===
function drawEdge(a, b, r) {
  // Calculate the vector between points a and b
  let dir = createVector(b.x - a.x, b.y - a.y, b.z - a.z);

  // Calculate the length of the vector (height of the cylinder)
  let h = dir.mag();

  // Push the current transformation matrix
  push();

  // Translate to the midpoint between a and b
  let mid = p5.Vector.add(a, b).mult(0.5);
  translate(mid.x, mid.y, mid.z);

  // Rotate to align the cylinder with the direction vector
  let zAxis = createVector(0, 1, 0); // The cylinder's default axis
  if (dir.x !== 0 || dir.z !== 0) {
    // General case: calculate rotation
    let rotationAxis = zAxis.cross(dir).normalize(); // Rotation axis
    let angle = acos(zAxis.dot(dir.normalize())); // Angle between vectors
    rotate(angle, rotationAxis);
  } else if (dir.y < 0) {
    // Special case: cylinder flipped along the y-axis
    rotate(PI, createVector(1, 0, 0));
  }

  // Draw the cylinder
  cylinder(r, h);

  // Restore the transformation matrix
  pop();
}

const rotCubesSeed = Date.now();

function rotatingCubes() {
	var t = millis()/10000;
	var n = floor(map(obj_density,0,10,2,12));
	push();
	colorMode(HSL,100);
	var angle = random();
	let palette = [];
	for (let i = 0; i<n; i++) {
		let c = color (angle, 100, 60);
		palette.push([red(c)/255, green(c)/255, blue(c)/255])
		angle += 100/n
	}
	pop();
	let a = random(1,3), b = random(1,3), c = random(1,3);
	noStroke()
	randomSeed(rotCubesSeed);
	ortho()
	var d = (cos(t)+1)*sz*0.2;
	var r = sz * map (cos(t),-1,1,0.2,0.1);
	let vtx = [[-r,-r,r], [-r,r,r], [r,r,r], [r, -r, r],
						 [-r,-r,-r], [-r,r,-r], [r,r,-r], [r, -r, -r],
						].map (p => createVector (...p));
	let edges = [[0,1],[1,2],[2,3],[3,0],
							 [4,5], [5,6], [6,7], [7,4],
							 [0,4],[1,5],[2,6],[3,7],
							]

	for (let i = 0; i < n; i += 1) {
		let {x,y} = createVector (d+sz/20,0).rotate(i*TAU/n+t*a);
		push();
		translate (x,y);
		rotateX(t*b*3)
		rotateY(t*c*3)
		paintShader.setUniform("u_color", [...palette[i],1]);
		for (let [j,k] of edges) {
			drawEdge(vtx[j],vtx[k],1.);
		}
		pop()
	}
}

